package com.bodylog.personal;
import android.content.*;import android.graphics.*;import android.util.Base64;import org.json.*;import java.io.*;import java.text.*;import java.util.*;import java.util.zip.*;
public final class BodyPhotoStore {
 static File dir(Context c){File f=new File(c.getFilesDir(),"body_photos");f.mkdirs();return f;}
 public static String normalPose(String p){return "side".equals(p)?"side":"back".equals(p)?"back":"front";}
 static boolean valid(String id){return id!=null&&id.matches("p_[0-9]{8}_[0-9]{9}_(front|side|back)\\.jpg");}
 static File file(Context c,String id){return valid(id)?new File(dir(c),id):null;}
 public static String latest(Context c,String pose){String best="";File[] fs=dir(c).listFiles();if(fs!=null)for(File f:fs)if(valid(f.getName())&&f.getName().endsWith("_"+normalPose(pose)+".jpg")&&f.getName().compareTo(best)>0)best=f.getName();return best;}
 public static String all(Context c){JSONArray a=new JSONArray();File[] files=dir(c).listFiles();if(files!=null){Arrays.sort(files,(x,y)->y.getName().compareTo(x.getName()));for(File f:files){String id=f.getName();if(!valid(id))continue;try{JSONObject o=new JSONObject();o.put("id",id);o.put("pose",id.substring(id.lastIndexOf('_')+1,id.length()-4));o.put("date",id.substring(2,6)+"-"+id.substring(6,8)+"-"+id.substring(8,10));o.put("time",id.substring(11,13)+":"+id.substring(13,15));a.put(o);}catch(Exception ignored){}}}return a.toString();}
 public static String imageData(Context c,String id,int maxSide){File f=file(c,id);if(f==null||!f.isFile())return "";try{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(f.getAbsolutePath(),o);o.inJustDecodeBounds=false;o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>maxSide*2)o.inSampleSize*=2;Bitmap b=BitmapFactory.decodeFile(f.getAbsolutePath(),o);if(b==null)return "";int size=Math.max(b.getWidth(),b.getHeight());Bitmap scaled=size>maxSide?Bitmap.createScaledBitmap(b,Math.max(1,b.getWidth()*maxSide/size),Math.max(1,b.getHeight()*maxSide/size),true):b;ByteArrayOutputStream out=new ByteArrayOutputStream();scaled.compress(Bitmap.CompressFormat.JPEG,78,out);if(scaled!=b)scaled.recycle();b.recycle();return "data:image/jpeg;base64,"+Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP);}catch(Exception e){return "";}}
 public static boolean delete(Context c,String id){File f=file(c,id);return f!=null&&f.delete();}
 public static String save(Context c,byte[] data,String pose){try{String id="p_"+new SimpleDateFormat("yyyyMMdd_HHmmssSSS",Locale.US).format(new Date())+"_"+normalPose(pose)+".jpg";try(FileOutputStream out=new FileOutputStream(file(c,id))){out.write(data);}return id;}catch(Exception e){return "";}}
 public static String importImage(Context c,InputStream in,String pose)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n,total=0;while((n=in.read(buf))!=-1){total+=n;if(total>20000000)throw new IOException("Large image");out.write(buf,0,n);}return save(c,out.toByteArray(),pose);}
 public static int exportZip(Context c,OutputStream out)throws IOException{ZipOutputStream zip=new ZipOutputStream(out);int count=0;File[] fs=dir(c).listFiles();if(fs!=null)for(File f:fs){if(!valid(f.getName()))continue;zip.putNextEntry(new ZipEntry(f.getName()));try(FileInputStream in=new FileInputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)zip.write(b,0,n);}zip.closeEntry();count++;}zip.finish();return count;}
 public static int restoreZip(Context c,InputStream in)throws IOException{ZipInputStream zip=new ZipInputStream(in);ZipEntry e;int count=0;long total=0;byte[] buf=new byte[8192];while((e=zip.getNextEntry())!=null){if(!valid(e.getName()))continue;if(++count>3000)throw new IOException("Too many");try(OutputStream out=new FileOutputStream(file(c,e.getName()))){int n;while((n=zip.read(buf))!=-1){total+=n;if(total>500000000)throw new IOException("Too large");out.write(buf,0,n);}}zip.closeEntry();}return count;}
}